import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long k = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        final long NEG = -1000000000000000000L;
        int kk = (int) k;
        long[] endHere = new long[kk + 1];
        long[] best = new long[kk + 1];
        Arrays.fill(endHere, NEG);
        Arrays.fill(best, NEG);
        best[0] = 0;
        for (int i = 0; i < n; i++) {
            long x = a[i];
            for (int j = kk; j >= 1; j--) {
                long e = Math.max(endHere[j], best[j - 1]) + x;
                endHere[j] = e;
                best[j] = Math.max(best[j], e);
            }
        }
        System.out.println(best[kk]);
    }
}
